import { describe, expect, it } from 'vitest'
import { DraftStore } from './DraftStore'

/**
 * Creates a fake storage that keeps items in a Map.
 * Generated by Claude Opus 5.5 High
 *
 * @returns A storage that works like localStorage.
 */
function createFakeStorage(): Storage {
  const items = new Map<string, string>()
  return {
    get length() {
      return items.size
    },
    clear: () => items.clear(),
    getItem: (key) => items.get(key) ?? null,
    key: (index) => [...items.keys()][index] ?? null,
    removeItem: (key) => items.delete(key),
    setItem: (key, value) => items.set(key, value),
  }
}

/**
 * Creates a fake storage that throws on every read and write.
 * Generated by Claude Opus 5.5 High
 *
 * @returns A storage that always fails.
 */
function createBrokenStorage(): Storage {
  const fail = () => {
    throw new Error('Storage is not available')
  }
  return { ...createFakeStorage(), getItem: fail, setItem: fail }
}

describe('DraftStore', () => {
  it('loads the draft it saved', () => {
    const draftStore = new DraftStore(createFakeStorage())
    draftStore.save('Hello world')
    expect(draftStore.load()).toBe('Hello world')
  })

  it('returns true when the draft is saved', () => {
    expect(new DraftStore(createFakeStorage()).save('Hello world')).toBe(true)
  })

  it('loads an empty string when nothing is saved', () => {
    expect(new DraftStore(createFakeStorage()).load()).toBe('')
  })

  it('returns false when the storage throws on save', () => {
    expect(new DraftStore(createBrokenStorage()).save('Hello world')).toBe(false)
  })

  it('loads an empty string when the storage throws on load', () => {
    expect(new DraftStore(createBrokenStorage()).load()).toBe('')
  })
})
